-- Table: hrm_leave_request
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_leave_request (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_number VARCHAR(50) NOT NULL UNIQUE,
    employee_id    BIGINT NOT NULL REFERENCES masterdata_employee(id),
    leave_type     VARCHAR(30) NOT NULL
                   CHECK (leave_type IN ('annual', 'sick', 'maternity', 'unpaid', 'other')),
    start_date     DATE NOT NULL,
    end_date       DATE NOT NULL,
    total_days     NUMERIC(9,2) NOT NULL DEFAULT 0 CHECK (total_days >= 0),
    reason         TEXT,
    status         VARCHAR(20) NOT NULL DEFAULT 'draft'
                   CHECK (status IN ('draft', 'created', 'approved', 'rejected', 'pending', 'completed', 'reopen')),
    requested_by   BIGINT REFERENCES masterdata_user(id),
    approved_by    BIGINT REFERENCES masterdata_user(id),
    approved_at    TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (start_date <= end_date)
);
